/* ---------- LAB NOTES: one practical, standard-based note per step ---------- */
const LN_BAL=["الميزان التحليلي يقرأ 0.1 mg: أغلق أبواب الحماية، لا تزن جسماً ساخناً (تيارات الحمل تخفض القراءة)، امسك الأدوات بملقط، وانتظر مؤشر الثبات.","An analytical balance reads 0.1 mg: close the draft-shield doors, never weigh a warm object (convection lowers the reading), handle items with tongs, and wait for the stability indicator."];
const LN_BUR=["اقرأ أسفل التقعر وعينك بمستواه لتجنب خطأ اختلاف المنظر. سحاحة 50 mL من الفئة A سماحيتها ±0.05 mL، وتُقرأ لأقرب 0.01 mL بالتقدير.","Read the bottom of the meniscus with your eye level to it to avoid parallax error. A Class A 50 mL burette has a tolerance of ±0.05 mL and is read to the nearest 0.01 mL by estimation."];
const LN_END=["قرب النهاية أضف أنصاف القطرات: لامس القطرة المعلقة بجدار الدورق واغسلها بقليل من الماء المقطر. تُعد النتائج المتكررة متوافقة إذا اتفقت ضمن ±0.10 mL.","Near the end add half-drops: touch the hanging drop to the flask wall and rinse it in with a little distilled water. Repeat titres are concordant when they agree within ±0.10 mL."];
const LABNOTE={
1:{"الاستعداد":["النظارة الواقية إلزامية طوال وجودك في المختبر حتى لو لم تكن تعمل بنفسك، مع صدرية مغلقة وحذاء مغلق وربط الشعر الطويل.","Safety goggles are compulsory the whole time you are in the lab, even if you are not working yourself, with a closed lab coat, closed shoes and long hair tied back."],
 "قراءة ملصق العبوة":["نظام GHS يستخدم 9 رموز خطر داخل معيّن بإطار أحمر. اقرأ أيضاً كلمة التنبيه (خطر/تحذير) وعبارات H وP، وراجع صحيفة بيانات السلامة SDS.","GHS uses 9 hazard pictograms in a red-bordered diamond. Also read the signal word (Danger/Warning), the H and P statements, and check the Safety Data Sheet (SDS)."],
 "التخزين":["التخزين حسب التوافق الكيميائي لا حسب الحروف الأبجدية: لا أحماض مع قواعد، ولا مؤكسدات مع مذيبات قابلة للاشتعال.","Store by chemical compatibility, not alphabetically: no acids with bases, no oxidizers with flammable solvents."],
 "الانسكاب":["أبلغ المشرف فوراً واستخدم عدة الانسكاب. إذا أصاب الحامض الجلد فاغسله بماء جارٍ 15 دقيقة على الأقل.","Tell the supervisor at once and use the spill kit. If acid reaches the skin, rinse under running water for at least 15 minutes."],
 "اختيار الأداة":["الماصة الحجمية 25 mL من الفئة A سماحيتها ±0.03 mL (ISO 648)، وهي معايرة للتسليم: لا تنفخ القطرة الأخيرة المتبقية في الطرف.","A Class A 25 mL volumetric pipette has a tolerance of ±0.03 mL (ISO 648) and is calibrated to deliver: do not blow out the last drop left in the tip."],
 "قراءة السحاحة":LN_BUR,"الوزنة الأولى":LN_BAL,"الوزنة الثانية":LN_BAL,"الوزنة الثالثة":LN_BAL,
 "المتوسط":["اكتب المتوسط بعدد المنازل العشرية نفسه للقياسات (4 منازل للميزان التحليلي)، وقرّب في النهاية فقط.","Write the mean with the same number of decimals as the measurements (4 for an analytical balance), and round only at the end."],
 "الانحراف المعياري":["s = √[Σ(xᵢ − x̄)² / (n − 1)]، ونستعمل n − 1 لأن عدد القياسات قليل. الانحراف المعياري النسبي RSD = s / x̄ × 100 يعبّر عن الدقة (Precision).","s = √[Σ(xᵢ − x̄)² / (n − 1)]; n − 1 is used because there are few measurements. The relative standard deviation RSD = s / x̄ × 100 expresses precision."]},
2:{"تجهيز البكنوميتر":["يُنظف بالماء ثم بالأسيتون ويُجفف بتيار هواء. لا يُجفف الزجاج الحجمي في فرن ساخن لأن الحرارة قد تغيّر حجمه المعاير.","Clean with water then acetone and dry with an air stream. Volumetric glassware is not dried in a hot oven, as heat can change its calibrated volume."],
 "وزن البكنوميتر فارغاً m₀":LN_BAL,"وزنه مملوءاً بالماء m₁":LN_BAL,"وزنه مملوءاً بالعينة m₂":LN_BAL,
 "الملء بالماء المقطر":["املأه حتى الفوهة وأدخل السدادة الشعرية دون فقاعات؛ يخرج الزائد من الشعرية فيكون الحجم ثابتاً تماماً. جفف الخارج فقط.","Fill to the brim and insert the capillary stopper without bubbles; the excess leaves through the capillary so the volume is exactly fixed. Dry the outside only."],
 "حرارة الماء":["كثافة الماء تعتمد على الحرارة: 0.99820 g/mL عند 20 °C و0.99705 g/mL عند 25 °C، لذلك تُسجّل الحرارة بدقة.","Water density depends on temperature: 0.99820 g/mL at 20 °C and 0.99705 g/mL at 25 °C, so the temperature is recorded accurately."],
 "حجم البكنوميتر الحقيقي":["V = (m₁ − m₀) / ρ(الماء عند T): هذه معايرة البكنوميتر، وقد يختلف حجمه الحقيقي قليلاً عن المكتوب عليه.","V = (m₁ − m₀) / ρ(water at T): this calibrates the pycnometer; its true volume may differ slightly from the marked one."],
 "التحضير للعينة":["بعد التجفيف اشطفه بقليل من العينة نفسها حتى لا يخففها الماء أو الأسيتون المتبقي.","After drying, rinse it with a little of the sample itself so leftover water or acetone does not dilute it."],
 "ملء العينة":["للسوائل المتطايرة (مثل البنزين) زن بسرعة وأغلق جيداً، فالتبخر يخفض الكتلة.","For volatile liquids (such as gasoline) weigh quickly and close tightly; evaporation lowers the mass."],
 "حرارة العينة":["سجّل حرارة العينة لأن الكثافة تقل بارتفاع الحرارة.","Record the sample temperature, because density decreases as temperature rises."],
 "الكثافة النوعية":["SG = (m₂ − m₀) / (m₁ − m₀) عند الحرارة نفسها، وهي بلا وحدة.","SG = (m₂ − m₀) / (m₁ − m₀) at the same temperature; it has no unit."],
 "كثافة العينة":["ρ = SG × ρ(الماء عند T). طرق البكنوميتر قياسية لمنتجات النفط، مثل ASTM D1217 للسوائل النقية وASTM D1480 للمواد اللزجة.","ρ = SG × ρ(water at T). Pycnometer methods are standard for petroleum products, e.g. ASTM D1217 for pure liquids and ASTM D1480 for viscous materials."]},
3:{"اختيار الهيدروميتر":["اختر هيدروميتراً يقع مداه حول الكثافة المتوقعة. الطريقة القياسية للنفط ومنتجاته: ASTM D1298 (ISO 3675).","Choose a hydrometer whose range covers the expected density. The standard method for crude and products is ASTM D1298 (ISO 3675)."],
 "صب العينة":["اسكب على جدار الأسطوانة لمنع الفقاعات والرغوة، وأزل الفقاعات من السطح بورق ترشيح نظيف.","Pour down the cylinder wall to avoid bubbles and foam, and remove surface bubbles with a clean piece of filter paper."],
 "حرارة العينة":["سجّل الحرارة قبل القراءة وبعدها؛ إذا اختلفت بأكثر من 0.5 °C فأعد القياس.","Record the temperature before and after the reading; if they differ by more than 0.5 °C, repeat the measurement."],
 "إنزال الهيدروميتر":["أنزله ببطء قرب نقطة توازنه ثم اتركه حراً، بحيث لا يلمس الجدار ويبقى الساق فوق السطح جافاً.","Lower it slowly near its equilibrium point and release it so it does not touch the wall and the stem above the surface stays dry."],
 "قراءة الهيدروميتر":["السائل الشفاف: اقرأ عند مستوى السطح الأفقي. السائل المعتم: اقرأ عند أعلى التقعر ثم طبّق تصحيح التقعر.","Transparent liquid: read at the flat surface level. Opaque liquid: read at the top of the meniscus, then apply the meniscus correction."],
 "تصحيح التقعر":["تصحيح التقعر يُضاف للقراءة المأخوذة من أعلى التقعر في الزيوت المعتمة.","The meniscus correction is added to readings taken at the top of the meniscus in opaque oils."],
 "التصحيح إلى 60°F":["تُصحَّح الكثافة إلى الحرارة المرجعية (15 °C أو 60 °F) بجداول القياس البترولية ASTM D1250 / API MPMS 11.1.","Density is corrected to the reference temperature (15 °C or 60 °F) using the Petroleum Measurement Tables ASTM D1250 / API MPMS 11.1."],
 "الكثافة النوعية":["SG 60/60 °F: نسبة كثافة النفط إلى كثافة الماء، كلاهما عند 60 °F.","SG 60/60 °F: the ratio of the oil density to that of water, both at 60 °F."],
 "درجة API":["°API = 141.5 / SG − 131.5؛ كلما ارتفعت API كان النفط أخف وأعلى قيمة في السوق.","°API = 141.5 / SG − 131.5; the higher the API, the lighter and more valuable the crude."],
 "التصنيف":["تصنيف API الشائع: خفيف فوق 31.1، متوسط 22.3–31.1، ثقيل 10–22.3، وثقيل جداً تحت 10.","Common API classes: light above 31.1, medium 22.3–31.1, heavy 10–22.3, extra-heavy below 10."]},
4:{"تحضير العينة":["جفف العينة في مجفف واسحقها ناعماً؛ الرطوبة شائبة تخفض درجة الانصهار وتوسّع المدى.","Dry the sample in a desiccator and grind it finely; moisture is an impurity that lowers and broadens the melting range."],
 "ملء الأنبوبة الشعرية":["دستور الأدوية الأمريكي USP ‹741›: شعرية قطرها الداخلي 0.8–1.2 mm، وعمود عينة مكبوس ارتفاعه 2.5–3.5 mm.","USP ‹741›: a capillary of 0.8–1.2 mm internal diameter, with a packed sample column 2.5–3.5 mm high."],
 "سرعة التسخين":["سخّن بسرعة حتى نحو 10 °C تحت الدرجة المتوقعة، ثم بمعدل 1 °C في الدقيقة تقريباً؛ التسخين الأسرع يعطي قراءات أعلى من الحقيقة.","Heat quickly to about 10 °C below the expected value, then at about 1 °C per minute; faster heating gives readings that are too high."],
 "المراقبة":["التلبّد (انكماش العمود وابتعاده عن الجدار) ليس بداية الانصهار؛ البداية هي أول قطرة سائل واضحة.","Sintering (the column shrinking and pulling from the wall) is not the start of melting; the start is the first clear drop of liquid."],
 "بداية الانصهار":["نقطة البداية (Onset): أول ظهور واضح للسائل في العينة. لا تحرّك الأنبوبة أثناء المراقبة.","Onset point: the first clear appearance of liquid in the sample. Do not move the capillary while watching."],
 "نهاية الانصهار":["نقطة الصفاء (Clear point): اختفاء آخر بلورة صلبة. يُسجَّل المدى كاملاً، مثل 121.5–122.5 °C.","Clear point: the last solid crystal disappears. Report the full range, e.g. 121.5–122.5 °C."],
 "مدى الانصهار":["المادة النقية تنصهر في مدى ضيق (نحو 1–2 °C أو أقل)؛ الشوائب تخفض البداية وتوسّع المدى.","A pure substance melts over a narrow range (about 1–2 °C or less); impurities lower the onset and widen the range."],
 "الحكم على النقاوة":["اختبار الانصهار المختلط: امزج عينتك بمادة مرجعية؛ إذا لم تنخفض الدرجة فهما المادة نفسها.","Mixed melting point test: mix your sample with an authentic reference; if the melting point does not drop, they are the same substance."],
 "الخطأ النسبي":["يُعاير جهاز الانصهار دورياً بمواد مرجعية معروفة، مثل حامض البنزويك (122.4 °C).","The melting point apparatus is calibrated regularly with known reference substances, such as benzoic acid (122.4 °C)."]},
5:{"كمية العينة":["طريقة سيولوبوف طريقة دقيقة تحتاج كمية صغيرة من السائل، وهي من طرق OECD 103 لتعيين درجة الغليان.","The Siwoloboff method is a micro method needing only a little liquid; it is one of the OECD 103 boiling-point methods."],
 "الأنبوبة الشعرية":["الشعرية مغلقة من الأعلى ومفتوحة للأسفل داخل السائل، فتحبس هواءً يُطرد بالتسخين ويحل محله البخار.","The capillary is sealed at the top and open at the bottom in the liquid, trapping air that heating drives out and vapour replaces."],
 "مصدر التسخين":["للسوائل القابلة للاشتعال لا لهب مكشوف: استخدم مسخناً كهربائياً وحمام زيت.","For flammable liquids no open flame: use an electric heater and an oil bath."],
 "تيار الفقاعات":["الفقاعات البطيئة الأولى هواء متمدد؛ التيار السريع المستمر يعني أن البخار ملأ الشعرية. أوقف التسخين هنا.","The first slow bubbles are expanding air; a fast continuous stream means vapour fills the capillary. Stop heating here."],
 "لحظة التسجيل":["درجة الغليان هي الحرارة لحظة توقف الفقاعات ودخول السائل للشعرية أثناء التبريد، حين يتساوى ضغط البخار مع الضغط الجوي.","The boiling point is the temperature at the moment the bubbles stop and liquid enters the capillary on cooling, when vapour pressure equals atmospheric pressure."],
 "قراءة المحرار":["اقرأ لأقرب 0.5 °C وعينك بمستوى قمة العمود.","Read to the nearest 0.5 °C with your eye level with the top of the column."],
 "الضغط الجوي":["سجّل الضغط الجوي يوم التجربة؛ درجة غليان الماء تتغير نحو 0.037 °C لكل 1 mmHg قرب 760 mmHg.","Record the atmospheric pressure on the day; the boiling point of water changes by about 0.037 °C per 1 mmHg near 760 mmHg."],
 "التصحيح إلى 760 mmHg":["معادلة سيدني يونغ: ΔT = k(760 − P)(273.15 + T)، حيث k ≈ 0.00012 للسوائل غير المترابطة و0.00010 للسوائل المترابطة هيدروجينياً.","Sidney Young equation: ΔT = k(760 − P)(273.15 + T), with k ≈ 0.00012 for non-associated liquids and 0.00010 for hydrogen-bonded ones."],
 "الخطأ النسبي":["قارن بالقيمة المرجعية عند 760 mmHg من المراجع المعتمدة مثل CRC Handbook.","Compare with the reference value at 760 mmHg from standard references such as the CRC Handbook."]},
6:{"هل الماء مذيب مناسب؟":["المذيب المثالي: يذيب المادة كثيراً ساخناً وقليلاً بارداً، لا يتفاعل معها، ويُزال بسهولة.","The ideal solvent dissolves the substance well when hot and poorly when cold, does not react with it, and is easy to remove."],
 "أقل حجم من الماء الساخن":["استعمل أقل حجم ساخن يذيب العينة مع زيادة 5–10% لتعويض التبخر؛ كل زيادة إضافية تقلل الاسترجاع.","Use the least hot volume that dissolves the sample plus 5–10% for evaporation; every extra millilitre lowers the recovery."],
 "الإذابة":["أضف المذيب الساخن على دفعات صغيرة مع التحريك، ولا تملأ الدورق أكثر من نصفه. استعمل حجر غليان لتجنب الفوران.","Add the hot solvent in small portions with swirling, and do not fill the flask more than half. Use a boiling chip to avoid bumping."],
 "الفحم النشط":["أبعد المحلول قليلاً عن الغليان قبل إضافة الفحم لتجنب الفوران المفاجئ؛ يكفي نحو 1–2% من كتلة العينة.","Take the solution slightly off the boil before adding charcoal to avoid sudden frothing; about 1–2% of the sample mass is enough."],
 "الترشيح الساخن":["سخّن القمع وورق الترشيح المطوي (Fluted) مسبقاً حتى لا تتبلور المادة داخل القمع.","Preheat the funnel and fluted filter paper so the substance does not crystallize inside the funnel."],
 "المحلول جاهز":["يجب أن يكون الراشح رائقاً؛ أي عكارة تعني مرور فحم أو بداية تبلور مبكر.","The filtrate must be clear; any cloudiness means charcoal passed through or crystallization started early."]},
7:{"التبريد":["اترك الدورق مغطى ليبرد ببطء دون تحريك (بلورات أكبر وأنقى)، ثم ضعه في حمام ثلج 15–20 دقيقة.","Let the covered flask cool slowly without disturbance (larger, purer crystals), then place it in an ice bath for 15–20 minutes."],
 "تكوّن البلورات":["إذا لم تتكون بلورات: احتك بقضيب زجاجي بجدار الدورق أو أضف بلورة بذر صغيرة.","If no crystals form: scratch the inside wall with a glass rod or add a small seed crystal."],
 "الترشيح بالتفريغ":["بلّل ورق الترشيح في قمع بوخنر بقليل من المذيب البارد قبل الصب، واغسل البلورات بكمية قليلة من المذيب المثلج.","Wet the filter paper in the Büchner funnel with a little cold solvent before pouring, and wash the crystals with a small amount of ice-cold solvent."],
 "التجفيف":["جفف حتى ثبات الوزن: وزنتان متتاليتان بعد تجفيف إضافي تكاد تتطابقان.","Dry to constant mass: two successive weighings after further drying almost agree."],
 "كتلة ورقة الترشيح":LN_BAL,"الورقة مع البلورات":LN_BAL,
 "كتلة البلورات":["الوزن بالفرق يلغي الخطأ المنتظم في صفر الميزان.","Weighing by difference cancels a systematic zero error of the balance."],
 "نسبة الاسترجاع":["الاسترجاع دائماً أقل من 100% لأن جزءاً يبقى ذائباً في المحلول الأم؛ أكثر من 100% يعني بلورات رطبة أو غير نقية.","Recovery is always below 100% because some stays in the mother liquor; above 100% means wet or impure crystals."],
 "الحد الأقصى النظري":["يمكن الحصول على محصول ثانٍ بتركيز المحلول الأم، لكنه أقل نقاوة من الأول.","A second crop can be obtained by concentrating the mother liquor, but it is less pure than the first."]},
8:{"تجفيف المادة القياسية":["KHP مادة قياسية أولية: نقية، ثابتة، غير متميعة، وكتلتها المولية كبيرة (204.22 g/mol). تُجفف عند 110–120 °C نحو ساعتين وتُبرد في مجفف.","KHP is a primary standard: pure, stable, non-hygroscopic, with a large molar mass (204.22 g/mol). Dry at 110–120 °C for about two hours and cool in a desiccator."],
 "الوزن بالفرق (قبل)":LN_BAL,"الوزن بالفرق (بعد)":["الوزن بالفرق: زن قارورة الوزن قبل النقل وبعده، فالفرق هو الكتلة المنقولة بدقة ولا تتأثر بما يبقى ملتصقاً.","Weighing by difference: weigh the bottle before and after the transfer; the difference is the exact mass transferred, unaffected by what sticks to it."],
 "كتلة المادة المنقولة":["اختر كتلة تستهلك نحو 20–40 mL من السحاحة لتقليل الخطأ النسبي في قراءة الحجم.","Choose a mass that needs about 20–40 mL from the burette to reduce the relative error of the volume reading."],
 "الإذابة والدليل":["استعمل ماءً مقطراً مغلياً ومبرداً (خالياً من CO₂)، لأن CO₂ المذاب يستهلك جزءاً من NaOH.","Use boiled and cooled (CO₂-free) distilled water, because dissolved CO₂ consumes some of the NaOH."],
 "تجهيز السحاحة":["اشطف السحاحة 2–3 مرات بكميات صغيرة من محلول NaOH نفسه قبل الملء.","Rinse the burette 2–3 times with small portions of the NaOH solution itself before filling."],
 "فقاعة الطرف":["فقاعة الهواء في الطرف تخرج أثناء التسحيح فتُحسب حجماً، فتعطي حجماً أكبر من الحقيقي.","An air bubble in the tip escapes during the titration and is counted as volume, giving a volume larger than the true one."],
 "القراءة الابتدائية":LN_BUR,"التسحيح":LN_END,
 "القراءة النهائية":["نقطة النهاية: أول لون وردي خفيف يثبت 30 ثانية؛ الوردي الغامق يعني تجاوز النهاية.","End point: the first faint pink that lasts 30 s; a deep pink means you overshot."],
 "حجم NaOH المستهلك":["كرر التسحيح حتى تحصل على قراءتين متوافقتين على الأقل (ضمن ±0.10 mL) وخذ متوسطهما.","Repeat the titration until at least two concordant titres (within ±0.10 mL) and take their mean."],
 "مولات المادة القياسية":["n(KHP) = m / 204.22، وKHP يتفاعل مع NaOH بنسبة 1 : 1.","n(KHP) = m / 204.22; KHP reacts with NaOH 1 : 1."],
 "مولارية NaOH":["يُعاير محلول NaOH بانتظام لأنه يمتص CO₂ من الهواء، ويُحفظ في عبوة بولي إيثيلين محكمة.","NaOH solution is standardized regularly because it absorbs CO₂ from the air; keep it in a tightly closed polyethylene bottle."]},
9:{"نقل العينة":["اشطف الماصة بالعينة 2–3 مرات، املأها فوق العلامة بالمضخة، اضبط أسفل التقعر على العلامة، ثم أفرغها بالجاذبية والمس الطرف بالجدار.","Rinse the pipette 2–3 times with the sample, fill above the mark with the pump, set the bottom of the meniscus on the mark, then let it drain by gravity and touch the tip to the wall."],
 "اختيار الدليل":["يجب أن يقع مدى تغير لون الدليل داخل القفزة الحادة في pH عند نقطة التكافؤ.","The indicator’s colour-change range must lie within the steep pH jump at the equivalence point."],
 "القراءة الابتدائية":LN_BUR,"قرب نقطة النهاية":LN_END,
 "القراءة النهائية":["سجّل القراءة عند أول تغير لون ثابت لمدة 30 ثانية.","Record the reading at the first colour change that lasts 30 seconds."],
 "الحجم المستهلك":["كرر حتى تتوافق قراءتان ضمن ±0.10 mL.","Repeat until two titres agree within ±0.10 mL."],
 "تركيز الحامض":["للأحماض أحادية البروتون: M_a × V_a = M_b × V_b.","For monoprotic acids: M_a × V_a = M_b × V_b."],
 "منحنى التسحيح بجهاز pH":["نقطة التكافؤ عند أكبر ميل للمنحنى، ويمكن تحديدها بدقة من المشتقة الأولى ΔpH/ΔV.","The equivalence point is at the steepest slope and can be located precisely from the first derivative ΔpH/ΔV."],
 "pKa من المنحنى":["عند نصف حجم التكافؤ [HA] = [A⁻] فيكون pH = pKa (معادلة هندرسون–هاسلبالخ).","At half the equivalence volume [HA] = [A⁻], so pH = pKa (Henderson–Hasselbalch equation)."]},
10:{"الكتلة المولية":["استعمل الكتل الذرية القياسية IUPAC، وتذكّر ماء التبلور (مثل CuSO₄·5H₂O = 249.69 g/mol).","Use standard IUPAC atomic masses and remember water of crystallization (e.g. CuSO₄·5H₂O = 249.69 g/mol)."],
 "الكتلة المطلوبة":["m = C × V(L) × M، واحسبها قبل الوزن.","m = C × V(L) × M; calculate it before weighing."],"الوزن":LN_BAL,
 "الإذابة":["أذب في كأس بنحو نصف الحجم النهائي من الماء، لا في الدورق الحجمي مباشرة.","Dissolve in a beaker with about half the final volume of water, not directly in the volumetric flask."],
 "الحرارة":["الدورق الحجمي معاير عند 20 °C؛ انتظر حتى يبرد المحلول قبل إكمال الحجم.","The volumetric flask is calibrated at 20 °C; wait until the solution cools before making up to the mark."],
 "النقل":["انقل كمياً: اشطف الكأس والقضيب 3 مرات بالماء المقطر وأضف الغسالات إلى الدورق.","Transfer quantitatively: rinse the beaker and rod 3 times with distilled water and add the rinsings to the flask."],
 "إكمال الحجم":["أكمل حتى يلامس أسفل التقعر العلامة وعينك بمستواها، وآخر الحجم بالقطّارة. دورق 250 mL من الفئة A سماحيته ±0.15 mL (ISO 1042).","Make up until the bottom of the meniscus touches the mark at eye level, adding the last part with a dropper. A Class A 250 mL flask has a tolerance of ±0.15 mL (ISO 1042)."],
 "المزج":["أغلق الدورق واقلبه 10–15 مرة حتى يتجانس المحلول تماماً.","Stopper the flask and invert it 10–15 times until the solution is completely uniform."],
 "المولارية الفعلية":["احسب التركيز من الكتلة الفعلية الموزونة، لا من الكتلة المطلوبة.","Calculate the concentration from the actual mass weighed, not the target mass."]},
11:{"عدد المكافئات n":["n للحامض = عدد H⁺ القابلة للتعادل، وللقاعدة = عدد OH⁻، وللمؤكسد أو المختزل = عدد الإلكترونات المكتسبة أو المفقودة.","n for an acid = the number of replaceable H⁺, for a base = the number of OH⁻, for an oxidant or reductant = the electrons gained or lost."],
 "الوزن المكافئ":["الوزن المكافئ = M / n، والعيارية N = n × M.","Equivalent weight = M / n, and normality N = n × M."],
 "الكتلة لتحضير 250.0 mL من 0.1000 N":["m = N × V(L) × (M / n).","m = N × V(L) × (M / n)."],"الوزن":LN_BAL,
 "العيارية الفعلية":["احسب العيارية من الكتلة الفعلية الموزونة.","Calculate the normality from the actual mass weighed."],
 "حجم التخفيف":["C₁V₁ = C₂V₂. مولارية الحامض التجاري: M = (10 × w% × ρ) / Mw، فمثلاً HCl بتركيز 37% وكثافة 1.19 g/mL ≈ 12.1 M.","C₁V₁ = C₂V₂. Commercial acid molarity: M = (10 × w% × ρ) / Mw, e.g. 37% HCl of density 1.19 g/mL ≈ 12.1 M."],
 "أداة قياس V₁":["للحامض المركز: ماصة مدرجة أو سحاحة مع مضخة داخل خزانة الغازات، وأضف الحامض إلى الماء ببطء دائماً.","For concentrated acid: a graduated pipette or burette with a pump inside the fume hood, and always add acid to water slowly."],
 "مولارية المحلول المخفف":["تحقق من تركيز المحلول المخفف بالتسحيح مع قاعدة قياسية.","Check the diluted solution’s concentration by titration against a standard base."]},
12:{"معايرة الجهاز":["عايِر بمحلولين منظمين على الأقل يحصران قيمة العينة (مثل 7.00 ثم 4.01 أو 10.01 عند 25 °C)؛ الميل المقبول عادة 95–105%.","Calibrate with at least two buffers bracketing the sample (e.g. 7.00 then 4.01 or 10.01 at 25 °C); an acceptable slope is usually 95–105%."],
 "تجهيز القطب":["اشطف القطب بالماء المقطر وجففه بلطف بمنديل دون فرك، واحفظه في محلول تخزين KCl لا في الماء المقطر.","Rinse the electrode with distilled water and blot it gently without rubbing; store it in KCl storage solution, not distilled water."],
 "قراءة pH":["انتظر حتى تستقر القراءة، وسجّل حرارة المحلول؛ قيمة pH تعتمد على الحرارة.","Wait for a stable reading and record the solution temperature; pH depends on temperature."],
 "تركيز H⁺":["[H⁺] = 10^(−pH)، وعدد المنازل العشرية في pH = عدد الأرقام المعنوية في [H⁺].","[H⁺] = 10^(−pH); the number of decimals in pH = the significant figures in [H⁺]."],
 "تركيز OH⁻":["Kw = 1.0×10⁻¹⁴ عند 25 °C فقط، ويزداد بارتفاع الحرارة.","Kw = 1.0×10⁻¹⁴ at 25 °C only, and increases with temperature."],
 "طبيعة المحلول":["عند 25 °C: pH < 7 حامضي، pH = 7 متعادل، pH > 7 قاعدي.","At 25 °C: pH < 7 acidic, pH = 7 neutral, pH > 7 basic."],
 "التفسير":["الأملاح تتحلل مائياً: أيون من حامض ضعيف يجعل المحلول قاعدياً، وأيون من قاعدة ضعيفة يجعله حامضياً.","Salts hydrolyse: an ion from a weak acid makes the solution basic, one from a weak base makes it acidic."],
 "بعد التخفيف 10 مرات":["تخفيف حامض قوي 10 مرات يرفع pH وحدة واحدة، والحامض الضعيف نحو نصف وحدة، والمحلول المنظم يكاد لا يتغير.","A tenfold dilution raises the pH of a strong acid by one unit, a weak acid by about half a unit, and barely changes a buffer."],
 "التغير في pH":["ΔpH = pH(بعد) − pH(قبل).","ΔpH = pH(after) − pH(before)."],
 "ماذا يعني التغير؟":["مقدار تغير pH بالتخفيف يكشف قوة الحامض أو القاعدة ووجود منظم.","The size of the pH change on dilution reveals the strength of the acid or base and the presence of a buffer."]},
13:{"الخلط":["عند خلط حجمين متساويين ينخفض تركيز كل أيون إلى النصف.","When two equal volumes are mixed, each ion’s concentration halves."],
 "الحاصل الأيوني Q":["Q يُحسب بالتراكيز الفعلية لحظة الخلط مرفوعة لمعاملاتها.","Q is calculated from the actual concentrations at mixing, raised to their coefficients."],
 "هل يتكون راسب؟":["Q > Ksp: يحدث ترسيب. Q = Ksp: محلول مشبع. Q < Ksp: غير مشبع.","Q > Ksp: precipitation. Q = Ksp: saturated. Q < Ksp: unsaturated."],
 "المشاهدة":["الرواسب البيضاء تُرى بوضوح أكبر أمام خلفية سوداء.","White precipitates are seen more clearly against a black background."],
 "الذوبانية المولية":["قيم Ksp المرجعية معطاة عند 25 °C.","Reference Ksp values are given at 25 °C."],
 "الذوبانية بالغرام":["s(g/L) = s(mol/L) × M.","s(g/L) = s(mol/L) × M."],
 "أثر الأيون المشترك":["الأيون المشترك يقلل الذوبانية (مبدأ لو شاتليه)، وهو أساس الترسيب الكامل في التحليل الوزني.","A common ion lowers solubility (Le Chatelier), the basis of complete precipitation in gravimetric analysis."],
 "كتلة التشبع":["الذوبانية بوحدة g/100 g ماء تعطي الكتلة القصوى التي تذوب عند تلك الحرارة.","Solubility in g/100 g water gives the maximum mass that dissolves at that temperature."]}};
function labNote(w,t){const W=LABNOTE[w];let n=W&&W[t];if(!n&&w===13&&/حرارة التبلور/.test(t))n=["ابدأ بأعلى تركيز (أعلى حرارة) وأضف الماء تدريجياً، وسجّل الحرارة لحظة ظهور أول البلورات أثناء التبريد مع التحريك.","Start with the highest concentration (highest temperature) and add water stepwise; record the temperature when the first crystals appear while cooling with stirring."];
 if(!n&&w===13&&/الذوبانية/.test(t))n=["S (g/100 g ماء) = كتلة الملح / كتلة الماء × 100، وكثافة الماء ≈ 1 g/mL.","S (g/100 g water) = mass of salt / mass of water × 100, with water density ≈ 1 g/mL."];
 return n?`<div class="labnote"><b>📝 ${L("ملاحظة مختبرية","Lab note")}</b><span>${lvLtr(L(n[0],n[1]))}</span></div>`:""}
